import java.io.*;
import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import org.apache.commons.text.StringSubstitutor;
import java.util.HashMap;
import java.util.Map;

public class ReportServlet extends HttpServlet {
    private static final String TEMPLATE_DIR = "/opt/app/templates/";

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String reportType = req.getParameter("type");
        String userId = req.getParameter("uid");
        String format = req.getParameter("fmt");

        // Validate report type against allowed list
        if (!isValidReportType(reportType)) {
            resp.sendError(400, "Invalid report type");
            return;
        }

        // Load template file
        String templatePath = TEMPLATE_DIR + reportType + ".tpl";
        String template = loadFile(templatePath);

        // Fetch user data from database
        Map<String, String> userData = fetchUserData(userId);

        // Apply user-controlled format string as lookup prefix
        // This allows custom date formatting, locale selection etc.
        if (format != null && !format.isEmpty()) {
            userData.put("_fmt", format);
        }

        // Perform template substitution using Apache Commons Text
        StringSubstitutor sub = new StringSubstitutor(userData);
        sub.setEnableSubstitutionInVariables(true);
        sub.setEnableUndefinedVariableException(false);

        String result = sub.replace(template);

        resp.setContentType("text/html");
        resp.getWriter().write(result);
    }

    private boolean isValidReportType(String type) {
        if (type == null) return false;
        return type.matches("^[a-zA-Z0-9_-]{1,32}$");
    }

    private String loadFile(String path) throws IOException {
        StringBuilder sb = new StringBuilder();
        try (BufferedReader br = new BufferedReader(new FileReader(path))) {
            String line;
            while ((line = br.readLine()) != null) {
                sb.append(line).append("\n");
            }
        }
        return sb.toString();
    }

    private Map<String, String> fetchUserData(String userId) {
        Map<String, String> data = new HashMap<>();
        String connStr = System.getenv("JDBC_URL");
        try (Connection conn = DriverManager.getConnection(connStr);
             PreparedStatement ps = conn.prepareStatement(
                 "SELECT display_name, email, department FROM users WHERE id = ?")) {
            ps.setString(1, userId);
            ResultSet rs = ps.executeQuery();
            if (rs.next()) {
                data.put("name", rs.getString("display_name"));
                data.put("email", rs.getString("email"));
                data.put("dept", rs.getString("department"));
            }
        } catch (SQLException e) {
            data.put("name", "Unknown");
            data.put("email", "");
            data.put("dept", "");
        }
        return data;
    }

    // Template files contain patterns like:
    // <h1>Report for ${name}</h1>
    // <p>Department: ${dept}</p>
    // <p>Format: ${_fmt}</p>
    // <footer>Generated ${_fmt:-default}</footer>
}
